import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { enableOtelLogging, initializeLogger, log } from './log.js';
import { loggerOptions, setLoggerState } from './log_core.js';
import {
  PinoCloudExporter,
  flushPinoLogs,
  initPinoCloudExporter,
} from './telemetry/pino_otel_transport.js';
import { REDACTED_EXCEPTION_MESSAGE } from './telemetry/utils.js';

const prettyMocks = vi.hoisted(() => ({ pinoPretty: vi.fn() }));

vi.mock('pino-pretty', async () => {
  const { PassThrough } = await import('node:stream');
  prettyMocks.pinoPretty.mockImplementation(() => new PassThrough());
  return { build: prettyMocks.pinoPretty };
});

const OTEL_ENABLED_KEY = Symbol.for('@livekit/agents:otelEnabled');

function entrypoint() {
  log().info('hello');
}

const entrypointLogLine =
  readFileSync(fileURLToPath(import.meta.url), 'utf8')
    .split('\n')
    .findIndex((line) => line.includes("log().info('hello')")) + 1;

function resetOtelLoggingState() {
  delete (globalThis as Record<symbol, unknown>)[OTEL_ENABLED_KEY];
  initializeLogger({ pretty: false, level: 'silent' });
}

// process.platform is non-writable and stdout.isTTY is absent off a TTY, so
// neither can be set by plain assignment.
function stubConsole(platform: NodeJS.Platform, isTTY: boolean | undefined) {
  Object.defineProperty(process, 'platform', { value: platform, configurable: true });
  Object.defineProperty(process.stdout, 'isTTY', { value: isTTY, configurable: true });
}

describe('pretty logging', () => {
  let initializePrettyLogger = initializeLogger;
  const { platform } = process;
  const { isTTY } = process.stdout;

  beforeAll(async () => {
    // vitest.setup.ts imported log.js before the pino-pretty mock above was
    // registered, so a fresh copy is needed to observe the mock.
    vi.resetModules();
    ({ initializeLogger: initializePrettyLogger } = await import('./log.js'));
  });

  afterEach(() => {
    stubConsole(platform, isTTY);
    prettyMocks.pinoPretty.mockClear();
    initializeLogger({ pretty: false, level: 'silent' });
  });

  it.each([
    ['win32', true, process.stdout],
    ['win32', false, undefined],
    ['linux', true, undefined],
  ] as const)(
    'selects the pino-pretty destination on %s when isTTY is %s',
    (platform, isTTY, destination) => {
      stubConsole(platform, isTTY);

      initializePrettyLogger({ pretty: true, level: 'silent' });

      expect(prettyMocks.pinoPretty).toHaveBeenCalledOnce();
      expect(prettyMocks.pinoPretty).toHaveBeenCalledWith({
        colorize: true,
        ...(destination && { destination }),
      });
    },
  );
});

describe('OTEL logging', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllEnvs();
    vi.unstubAllGlobals();
    resetOtelLoggingState();
  });

  it('exports logs from logger instances captured before OTEL is enabled', async () => {
    initializeLogger({ pretty: false, level: 'info' });
    const staleLogger = log().child({ capturedBeforeOtel: true });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});

    initPinoCloudExporter({
      observabilityUrl: 'https://example.livekit.cloud',
      roomId: 'RM_test',
      jobId: 'AJ_test',
    });
    enableOtelLogging();

    staleLogger.info('log from stale logger');
    log().info('log from fresh logger');

    await vi.waitFor(() => {
      const messages = emitSpy.mock.calls.map(([logObj]) => logObj.msg);
      expect(messages).toContain('log from stale logger');
      expect(messages).toContain('log from fresh logger');
    });
  });

  it('exports sensitive content as a redactable attribute instead of log body text', async () => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});

    initPinoCloudExporter({
      observabilityUrl: 'https://example.livekit.cloud',
      roomId: 'RM_test',
      jobId: 'AJ_test',
    });
    enableOtelLogging();

    log().info({ 'lk.pii.user_input': 'secret transcript' }, 'received user input');

    await vi.waitFor(() => {
      const record = emitSpy.mock.calls
        .map(([logObj]) => logObj)
        .find((logObj) => {
          return logObj.msg === 'received user input';
        });
      expect(record).toMatchObject({
        msg: 'received user input',
        'lk.pii.user_input': 'secret transcript',
      });
      expect(record?.msg).not.toContain('secret transcript');
    });
  });

  it('keeps operational errors, reasons, framework URLs, and resource IDs in non-PII fields', async () => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});

    initPinoCloudExporter({
      observabilityUrl: 'https://example.livekit.cloud',
      roomId: 'RM_test',
      jobId: 'AJ_test',
    });
    enableOtelLogging();

    log().error({ error: new Error('connection failed') }, 'provider failed');
    log().warn({ reason: 'remote close' }, 'provider disconnected');
    log().info({ baseUrl: 'wss://example.livekit.cloud' }, 'connecting to framework');
    log().info({ avatarId: 'avatar-123' }, 'avatar session started');

    await vi.waitFor(() => {
      const records = emitSpy.mock.calls.map(([logObj]) => logObj);
      const errorRecord = records.find((logObj) => logObj.msg === 'provider failed');
      expect(errorRecord).toMatchObject({
        msg: 'provider failed',
        error: {
          type: 'Error',
          message: 'connection failed',
        },
      });
      expect(errorRecord).not.toHaveProperty('lk.pii.error');

      const reasonRecord = records.find((logObj) => logObj.msg === 'provider disconnected');
      expect(reasonRecord).toMatchObject({
        msg: 'provider disconnected',
        reason: 'remote close',
      });
      expect(reasonRecord).not.toHaveProperty('lk.pii.reason');

      const connectionRecord = records.find((logObj) => logObj.msg === 'connecting to framework');
      expect(connectionRecord).toMatchObject({
        msg: 'connecting to framework',
        baseUrl: 'wss://example.livekit.cloud',
      });
      expect(connectionRecord).not.toHaveProperty('lk.pii.base_url');

      const avatarRecord = records.find((logObj) => logObj.msg === 'avatar session started');
      expect(avatarRecord).toMatchObject({
        msg: 'avatar session started',
        avatarId: 'avatar-123',
      });
      expect(avatarRecord).not.toHaveProperty('lk.pii.avatar_id');
    });
  });

  it.each([
    ['error', false],
    ['error', true],
    ['err', false],
    ['err', true],
  ] as const)(
    'redacts serialized %s details when redaction is %s',
    async (exceptionKey, redactionEnabled) => {
      vi.stubEnv('LIVEKIT_API_KEY', 'devkey');
      vi.stubEnv('LIVEKIT_API_SECRET', 'secret');
      const fetchMock = vi.fn().mockResolvedValue({ ok: true });
      vi.stubGlobal('fetch', fetchMock);
      initializeLogger({ pretty: false, level: 'info' });

      initPinoCloudExporter({
        observabilityUrl: 'https://example.livekit.cloud',
        roomId: 'RM_test',
        jobId: 'AJ_test',
        metadata: { 'lk.redaction.enabled': redactionEnabled },
      });
      enableOtelLogging();

      const exception = new Error('secret transcript', {
        cause: new Error('secret nested cause'),
      }) as Error & { body: unknown };
      exception.body = { transcript: 'secret provider payload' };
      log().error({ [exceptionKey]: exception }, 'provider failed');
      await flushPinoLogs();

      expect(fetchMock).toHaveBeenCalledOnce();
      const requestBody = fetchMock.mock.calls[0]![1].body as string;
      const payload = JSON.parse(requestBody) as {
        resourceLogs: Array<{
          scopeLogs: Array<{
            logRecords: Array<{
              attributes: Array<{ key: string; value: { stringValue?: string } }>;
            }>;
          }>;
        }>;
      };
      const attributes = payload.resourceLogs[0]!.scopeLogs[0]!.logRecords[0]!.attributes;
      const serializedError = attributes.find(({ key }) => key === exceptionKey)?.value.stringValue;
      expect(serializedError).toBeDefined();
      const error = JSON.parse(serializedError!) as Record<string, unknown>;

      if (redactionEnabled) {
        expect(error).toEqual({
          type: 'Error',
          message: REDACTED_EXCEPTION_MESSAGE,
        });
        expect(requestBody).not.toContain('secret transcript');
        expect(requestBody).not.toContain('secret nested cause');
        expect(requestBody).not.toContain('secret provider payload');
      } else {
        expect(error.message).toContain('secret transcript');
        expect(error.message).toContain('secret nested cause');
        expect(error.stack).toContain('secret transcript');
        expect(error.body).toEqual({ transcript: 'secret provider payload' });
      }
    },
  );
});

describe('log metadata', () => {
  beforeEach(() => {
    initPinoCloudExporter({
      observabilityUrl: 'https://example.livekit.cloud',
      roomId: 'RM_test',
      jobId: 'AJ_test',
    });
  });

  afterEach(() => {
    vi.restoreAllMocks();
    resetOtelLoggingState();
  });

  it('adds code attributes', async () => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});
    enableOtelLogging();

    entrypoint();

    await vi.waitFor(() => {
      const record = emitSpy.mock.calls
        .map(([logObj]) => logObj)
        .find(({ msg }) => msg === 'hello');
      expect(record).toMatchObject({
        'code.file.path': fileURLToPath(import.meta.url),
        'code.function.name': 'entrypoint',
        'code.line.number': entrypointLogLine,
      });
    });
  });

  it.each([false, true])('adds current job context to cached loggers (pretty: %s)', (pretty) => {
    initializeLogger({ pretty, level: 'info' });
    const cached = log().child({ component: 'prewarmed' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});
    enableOtelLogging();

    cached.info('before job');
    expect(emitSpy.mock.calls.at(-1)?.[0]).not.toHaveProperty('agent_name');

    const context = { jobID: 'AJ_named', room_id: 'RM_named', agent_name: 'named-agent' };
    setLoggerState(log().child(context), loggerOptions()!);
    cached.info('cached logger');
    log().info('current logger');

    expect(emitSpy.mock.calls.at(-2)?.[0]).toMatchObject({
      ...context,
      component: 'prewarmed',
      msg: 'cached logger',
    });
    expect(emitSpy.mock.calls.at(-1)?.[0]).toMatchObject({ ...context, msg: 'current logger' });
    if (pretty) {
      expect(emitSpy.mock.calls.at(-1)?.[0]).not.toHaveProperty('code.file.path');
    }

    initializeLogger({ pretty, level: 'info' });
    cached.info('after reset');
    expect(emitSpy.mock.calls.at(-1)?.[0]).not.toHaveProperty('agent_name');
  });

  it.each([
    { 'code.file.path': '/reported/source.ts' },
    { 'code.function.name': 'reported' },
    { 'code.line.number': 42 },
    { 'code.file.path': null },
  ])('preserves child code attributes: %j', (bindings) => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});
    enableOtelLogging();

    const child = log().child(bindings);
    child.info('child attributes');
    expect(emitSpy.mock.calls.at(-1)?.[0]).toMatchObject(bindings);
    expect(emitSpy.mock.calls.at(-1)?.[0]).toHaveProperty('code.line.number');
    expect(emitSpy.mock.calls.at(-1)?.[0]).toHaveProperty('code.function.name');

    const override = {
      'code.file.path': '/override.ts',
      'code.function.name': 'override',
      'code.line.number': 84,
    };
    child.info(override, 'call attributes');
    expect(emitSpy.mock.calls.at(-1)?.[0]).toMatchObject(override);
  });

  it.each([
    '/app/node_modules/@opentelemetry/instrumentation-pino/build/src/instrumentation.js',
    'C:\\app\\node_modules\\@opentelemetry\\instrumentation-pino\\build\\src\\instrumentation.js',
  ])('skips the Pino instrumentation frame at %s', (instrumentationPath) => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});
    enableOtelLogging();
    vi.spyOn(Error, 'captureStackTrace').mockImplementation((holder) => {
      Object.assign(holder, {
        stack: `Error\n    at logger.<computed> (${instrumentationPath}:45:71)\n    at Pino.write (/app/node_modules/pino/lib/proto.js:204:16)\n    at entrypoint (${import.meta.url}:42:9)`,
      });
    });

    log().info('instrumented logger');
    expect(emitSpy.mock.calls.at(-1)?.[0]).toMatchObject({
      'code.file.path': fileURLToPath(import.meta.url),
      'code.function.name': 'entrypoint',
      'code.line.number': 42,
    });
  });

  it.each([
    [
      'throws',
      () => {
        throw new Error('broken hook');
      },
    ],
    ['returns call sites', (_error: Error, callSites: NodeJS.CallSite[]) => callSites],
  ])('still logs when a global Error.prepareStackTrace %s', async (_name, prepareStackTrace) => {
    initializeLogger({ pretty: false, level: 'info' });
    const emitSpy = vi.spyOn(PinoCloudExporter.prototype, 'emit').mockImplementation(() => {});
    enableOtelLogging();

    const original = Error.prepareStackTrace;
    Error.prepareStackTrace = prepareStackTrace;
    try {
      expect(() => log().info('broken stack')).not.toThrow();
    } finally {
      Error.prepareStackTrace = original;
    }

    await vi.waitFor(() => {
      const record = emitSpy.mock.calls
        .map(([logObj]) => logObj)
        .find(({ msg }) => msg === 'broken stack');
      expect(record).toBeDefined();
      expect(record).not.toHaveProperty('code.file.path');
    });
  });
});
